const ZoneSpritePixels *zone_sprite_pixels(int32_t sprite_id) {
  size_t lo = 0, hi = sizeof(kSprites) / sizeof(kSprites[0]);
  while (lo < hi) {
    size_t mid = lo + (hi - lo) / 2;
    if (kSprites[mid].sprite_id < sprite_id) lo = mid + 1; else hi = mid;
  }
  if (lo < sizeof(kSprites) / sizeof(kSprites[0]) && kSprites[lo].sprite_id == sprite_id) return &kSprites[lo];
  return 0;
}

size_t zone_sprite_count(void) { return sizeof(kSprites) / sizeof(kSprites[0]); }
